:root{--ink:#17212b;--paper:#edf2f3;--card:#fff;--blue:#176b87;--green:#31745c;--red:#d85d4c;--line:#cad8dc;--muted:#68777d}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#edf2f3,#f8eee7);color:var(--ink);font-family:Arial,sans-serif}main{width:min(1080px,calc(100% - 40px));margin:auto;padding:28px 0 70px}nav{display:flex;justify-content:space-between;font-size:13px;font-weight:700}nav a{color:var(--blue);text-decoration:none}header{margin:65px 0 32px;max-width:750px}.eyebrow{color:var(--red);font-size:12px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}h1{margin:10px 0;font:400 clamp(2.8rem,7vw,6rem)/.9 Georgia,serif;letter-spacing:-.06em}.intro{color:var(--muted);font-size:16px;line-height:1.6}.layout{display:grid;grid-template-columns:320px 1fr;gap:20px;align-items:start}section{border:1px solid var(--line);background:rgba(255,255,255,.9);padding:24px;box-shadow:8px 8px 0 rgba(23,107,135,.08)}label{display:block;margin:17px 0 6px;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}input{width:100%;padding:13px;border:1px solid #afc0c5;font:20px Georgia,serif}button{width:100%;margin-top:22px;padding:15px;border:0;background:var(--red);color:#fff;cursor:pointer;font-weight:800;text-transform:uppercase}.run-title{display:flex;justify-content:space-between;align-items:center}h2{margin:0;font:400 28px Georgia,serif}.state{color:var(--blue);font-weight:800;text-transform:uppercase}progress{width:100%;height:18px;margin:22px 0;accent-color:var(--blue)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{padding:15px;border-top:3px solid var(--blue);background:#f5f9fa}.stat span{display:block;color:var(--muted);font-size:10px;font-weight:800;text-transform:uppercase}.stat strong{display:block;margin-top:7px;color:var(--blue);font:400 28px Georgia,serif}.explain{margin-top:20px;padding:15px;background:#edf7f1;color:var(--green);font-size:14px;line-height:1.5}.note{color: