<section style="margin-top:20px;overflow:auto"><h2>Histórico de consumos</h2><p class="note">Execuções com totais diferentes são incompletas; a vazão só considera mensagens processadas e contabilizadas.</p><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Encerrado em</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Situação</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Mensagens</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Processadas</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Diferença</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Configurados / ativos</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Tempo até zerar</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Vazão (msg/s)</th><th style="text-align:left;padding:10px;border-bottom:1px solid var(--line)">Backlog final</th></tr></thead><tbody>@foreach ($history as $run)<tr><td style="padding:10px;border-bottom:1px solid var(--line)">{{ isset($run['completed_at']) ? \Illuminate\Support\Carbon::parse($run['completed_at'])->format('d/m/Y H:i') : '-' }}</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ (($run['status'] ?? null) === 'incomplete' || (int) ($run['processed'] ?? 0) !== (int) ($run['published'] ?? 0)) ? 'Incompleto' : 'Concluído' }}</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ number_format($run['published'] ?? 0, 0, ',', '.') }}</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ number_format($run['processed'] ?? 0, 0, ',', '.') }}</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ number_format(abs((int) ($run['published'] ?? 0) - (int) ($run['processed'] ?? 0)), 0, ',', '.') }}</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ $run['requested_consumers'] ?? '-' }} / {{ $run['consumers'] ?? 0 }}</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ number_format(($run['consumer_elapsed_ms'] ?? $run['elapsed_ms'] ?? 0) / 1000, 2, ',', '.') }}s</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ (int) ($run['processed'] ?? 0) === (int) ($run['published'] ?? 0) ? number_format($run['throughput'] ?? 0, 2, ',', '.') : '-' }}</td><td style="padding:10px;border-bottom:1px solid var(--line)">{{ $run['backlog'] ?? 0 }}</td></tr>@endforeach</tbody></table></section>
