@if(session('consumer_run_id'))<script>(function(){const runId=@json(session('consumer_run_id'));const url=@json(url('/consumer-lab/status'))+'?run_id='+encodeURIComponent(runId);const set=(id,value)=>document.getElementById(id).textContent=value;const poll=()=>fetch(url,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(run=>{const published=Number(run.published||0),processed=Number(run.processed||0),backlog=Number(run.backlog||0),difference=published-processed;set('state',run.status==='completed'?'finalizado':run.status==='incomplete'?'incompleto':run.status);set('published',published.toLocaleString('pt-BR'));set('processed',processed.toLocaleString('pt-BR'));set('backlog',backlog.toLocaleString('pt-BR'));set('consumers',Number(run.consumers||0).toLocaleString('pt-BR'));set('elapsed',((run.elapsed_ms||0)/1000).toFixed(2).replace('.',',')+'s');set('difference',Math.abs(difference).toLocaleString('pt-BR'));document.getElementById('progress').max=Math.max(1,published);document.getElementById('progress').value=processed;set('explain',run.status==='completed'?'Todos os eventos publicados foram processados. A fila está saudável.':run.status==='incomplete'?'Divergência: '+Math.abs(difference).toLocaleString('pt-BR')+' mensagens não conferem entre publicação e processamento.':backlog>0?'A fila ainda possui '+backlog.toLocaleString('pt-BR')+' mensagens aguardando consumo.':'Aguardando o publisher e os consumers iniciarem.');if((run.status!=='completed'&&run.status!=='incomplete')||backlog>0)window.setTimeout(poll,700)}).catch(()=>window.setTimeout(poll,1200));poll()}())</script>@endif
